<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/layout.php'; require_login(); require_perm(can('reservations')?'reservations':'reservations_view'); $pdo=pdo();
if($_SERVER['REQUEST_METHOD']==='POST' && can('reservations')){
 $days=days_between(post('date_debut'),post('date_fin')); $prix=(float)post('prix_jour'); $remise=(float)post('remise',0); $total=max(0,$days*$prix-$remise); $avance=(float)post('avance',0); $reste=max(0,$total-$avance); $ref=post('reference') ?: ref_reservation();
 $fields=['reference','client_id','voiture_id','date_debut','date_fin','heure_depart','heure_retour','lieu_depart','lieu_retour','prix_jour','remise','total','avance','reste','statut','avec_conducteur2','conducteur2_nom','conducteur2_prenom','conducteur2_nationalite','conducteur2_cin','conducteur2_passport','conducteur2_permis','conducteur2_telephone','conducteur2_adresse','conditions'];
 $vals=[$ref,post('client_id'),post('voiture_id'),post('date_debut'),post('date_fin'),post('heure_depart'),post('heure_retour'),post('lieu_depart'),post('lieu_retour'),$prix,$remise,$total,$avance,$reste,post('statut','Réservée'),post('avec_conducteur2')?1:0,post('conducteur2_nom'),post('conducteur2_prenom'),post('conducteur2_nationalite'),post('conducteur2_cin'),post('conducteur2_passport'),post('conducteur2_permis'),post('conducteur2_telephone'),post('conducteur2_adresse'),post('conditions')];
 if(post('id')){ $set=implode(',',array_map(fn($f)=>"$f=?",$fields)); $pdo->prepare("UPDATE reservations SET $set WHERE id=?")->execute([...$vals,post('id')]); flash('Réservation modifiée.'); } else { $cols=implode(',',$fields); $qs=implode(',',array_fill(0,count($fields),'?')); $pdo->prepare("INSERT INTO reservations($cols) VALUES($qs)")->execute($vals); flash('Réservation créée avec contrat prêt.'); }
 $pdo->prepare("UPDATE voitures SET statut=CASE WHEN ? IN ('Réservée','En cours') THEN 'Louée' ELSE 'Disponible' END WHERE id=?")->execute([post('statut','Réservée'),post('voiture_id')]); redirect('/reservations.php');
}
if(getv('delete') && can('reservations')){$pdo->prepare('DELETE FROM reservations WHERE id=?')->execute([getv('delete')]);flash('Réservation supprimée.');redirect('/reservations.php');}
$edit=null; if(getv('edit')){$st=$pdo->prepare('SELECT * FROM reservations WHERE id=?');$st->execute([getv('edit')]);$edit=$st->fetch();}
$clients=$pdo->query("SELECT id, CONCAT(nom,' ',prenom,' - ',COALESCE(telephone,'')) label FROM clients ORDER BY nom")->fetchAll();
$cars=$pdo->query("SELECT id, CONCAT(immatriculation,' - ',marque,' ',modele,' (',statut,')') label, cout_jour FROM voitures ORDER BY marque")->fetchAll();
$rows=$pdo->query("SELECT r.*, CONCAT(c.nom,' ',c.prenom) client, CONCAT(v.marque,' ',v.modele,' - ',v.immatriculation) voiture FROM reservations r JOIN clients c ON c.id=r.client_id JOIN voitures v ON v.id=r.voiture_id ORDER BY r.id DESC")->fetchAll();
render_header('Réservations et contrats'); ?>
<section class="panel"><div class="panel-head"><h2>Réservations</h2><?php if(can('reservations')):?><a class="btn primary" href="/reservations.php?action=new">+ Nouvelle réservation</a><?php endif;?></div>
<?php if((getv('action')==='new'||$edit) && can('reservations')):$r=$edit??[]; ?><form method="post" class="form-grid reservation-form"><input type="hidden" name="id" value="<?=e($r['id']??'')?>"><input type="hidden" name="reference" value="<?=e($r['reference']??'')?>"><label>Client<select name="client_id" required><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=$c['id']==($r['client_id']??'')?'selected':''?>><?=e($c['label'])?></option><?php endforeach;?></select></label><label>Véhicule<select name="voiture_id" id="carSelect" required><?php foreach($cars as $c):?><option value="<?=$c['id']?>" data-price="<?=$c['cout_jour']?>" <?=$c['id']==($r['voiture_id']??'')?'selected':''?>><?=e($c['label'])?></option><?php endforeach;?></select></label><label>Date début<input type="date" name="date_debut" id="dateDebut" required value="<?=e($r['date_debut']??date('Y-m-d'))?>"></label><label>Date fin<input type="date" name="date_fin" id="dateFin" required value="<?=e($r['date_fin']??date('Y-m-d'))?>"></label><label>Heure départ<input name="heure_depart" value="<?=e($r['heure_depart']??'09:00')?>"></label><label>Heure retour<input name="heure_retour" value="<?=e($r['heure_retour']??'18:00')?>"></label><label>Lieu départ<input name="lieu_depart" value="<?=e($r['lieu_depart']??'Agence LAHLAL CAR')?>"></label><label>Lieu retour<input name="lieu_retour" value="<?=e($r['lieu_retour']??'Agence LAHLAL CAR')?>"></label><label>Prix / jour<input type="number" step="0.01" name="prix_jour" id="prixJour" value="<?=e($r['prix_jour']??0)?>"></label><label>Remise<input type="number" step="0.01" name="remise" id="remise" value="<?=e($r['remise']??0)?>"></label><label>Avance<input type="number" step="0.01" name="avance" id="avance" value="<?=e($r['avance']??0)?>"></label><label>Statut<select name="statut"><?php foreach(['Réservée','En cours','Terminée','Annulée'] as $s):?><option <?=$s===($r['statut']??'Réservée')?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><div class="summary span2"><b>Total estimé : <span id="totalCalc">0 DH</span></b><span>Reste : <span id="resteCalc">0 DH</span></span></div><label class="span2 checkbox"><input type="checkbox" name="avec_conducteur2" id="toggleDriver2" <?=($r['avec_conducteur2']??0)?'checked':''?>> Ajouter un 2ᵉ conducteur au contrat</label><div class="driver2 span2" id="driver2Box"><h3>Informations du 2ᵉ conducteur</h3><div class="form-grid inner"><label>Nom<input name="conducteur2_nom" value="<?=e($r['conducteur2_nom']??'')?>"></label><label>Prénom<input name="conducteur2_prenom" value="<?=e($r['conducteur2_prenom']??'')?>"></label><label>Nationalité<input name="conducteur2_nationalite" value="<?=e($r['conducteur2_nationalite']??'')?>"></label><label>CIN<input name="conducteur2_cin" value="<?=e($r['conducteur2_cin']??'')?>"></label><label>Passeport<input name="conducteur2_passport" value="<?=e($r['conducteur2_passport']??'')?>"></label><label>N° permis<input name="conducteur2_permis" value="<?=e($r['conducteur2_permis']??'')?>"></label><label>Téléphone<input name="conducteur2_telephone" value="<?=e($r['conducteur2_telephone']??'')?>"></label><label>Adresse<input name="conducteur2_adresse" value="<?=e($r['conducteur2_adresse']??'')?>"></label></div></div><label class="span2">Conditions / remarques<textarea name="conditions"><?=e($r['conditions']??'Le véhicule doit être rendu dans le même état, avec les documents et accessoires remis au départ.')?></textarea></label><div class="form-actions span2"><button class="btn primary">Enregistrer</button><a class="btn" href="/reservations.php">Annuler</a></div></form><?php endif; ?>
<div class="table-wrap"><table><thead><tr><th>Réf</th><th>Client</th><th>Véhicule</th><th>Période</th><th>Montant</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['reference'])?></b></td><td><?=e($r['client'])?></td><td><?=e($r['voiture'])?></td><td><?=e($r['date_debut'])?> → <?=e($r['date_fin'])?></td><td><?=money($r['total'])?><small>Reste: <?=money($r['reste'])?></small></td><td><span class="badge"><?=e($r['statut'])?></span></td><td class="actions"><a class="btn small" href="/contrat.php?id=<?=$r['id']?>" target="_blank">Contrat</a><?php if(can('reservations')):?><a class="btn small" href="/reservations.php?edit=<?=$r['id']?>">Modifier</a><a class="btn small danger" data-confirm="Supprimer ?" href="/reservations.php?delete=<?=$r['id']?>">Supprimer</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php render_footer(); ?>
